import json

# Count differences between input and output
print("Analyzing demo transformation...")
changes = []
for i in range(len(demo_pairs[0]['output'])):
    if demo_pairs[0]['output'][i] != demo_pairs[0]['input'][i]:
        changes.append(i)
print(f"Changed rows: {changes}")

# For each changed row, find where the output came from
for i in changes:
    output_row = demo_pairs[0]['output'][i]
    found = False
    for j in range(len(demo_pairs[0]['input'])):
        if output_row == demo_pairs[0]['input'][j]:
            print(f"output[{i}] came from input[{j}]")
            found = True
            break
    if not found:
        print(f"output[{i}] not found in input (ERROR)")

# Count transitions again
transitions = 0
for i in range(len(demo_pairs[0]['input'])-1):
    if demo_pairs[0]['input'][i] != demo_pairs[0]['input'][i+1]:
        transitions += 1
print(f"\nTransitions: {transitions}")

# Height
height = len(demo_pairs[0]['input'])
print(f"Height: {height}")

# Find homogeneous block at the end
homogeneous_start = None
for i in range(height - 1, 0, -1):
    if all(demo_pairs[0]['input'][i] == demo_pairs[0]['input'][i+1]):
        homogeneous_start = i
print(f"Homogeneous block starts at row: {homogeneous_start if homogeneous_start else 'none'}")
if homogeneous_start:
    hom_len = height - homogeneous_start
    print(f"Block length: {hom_len}")

# Let me analyze each changed row and its shift amount more carefully
