      [8,8,7], [7,8,7], [7,7,7], [7,7,7], [7,7,7], [7,7,7],
      [7,7,7], [7,7,7], [7,7,7]
    ]
  }
]

# For each row that changed, find what input row it came from
print("Demo analysis:")
for i, row in enumerate(demo_pairs[0]['output']):
    matched = None
    for j, input_row in enumerate(demo_pairs[0]['input']):
        if row == input_row:
            matched = (j, j-i)
            break
    print(f"  output[{i}] = input[{matched[0]}] (shift = {matched[1] if matched else 'N/A'})")

print("\nFor unchanged rows:")
for i, row in enumerate(demo_pairs[0]['output']):
    if row == demo_pairs[0]['input'][i]:
        print(f"  output[{i}] unchanged = input[{i}]")

# Count transitions again
transitions = sum(1 for i in range(len(demo_pairs[0]['input'])-1) 
                  if demo_pairs[0]['input'][i] != demo_pairs[0]['input'][i+1])
print(f"\nDemo: {transitions} transitions")

# Fix the matching - need to find the MOST LIKELY match (minimum shift)

demo_pairs = [
  {
    "input": [
      [7,7,7], [8,7,7], [8,8,8], [8,8,8], [7,7,8], [7,8,7],
      [8,8,7], [7,8,7], [7,7,7], [7,7,7], [7,7,7], [7,7,7],
