      [7,7,7], [7,7,7], [7,7,7]
    ]
  }
]

# For each CHANGED row, find the MOST LIKELY input source (minimum shift)
print("Changed rows analysis:")
for i, out_row in enumerate(demo_pairs[0]['output']):
    if out_row != demo_pairs[0]['input'][i]:
        # Find matching input rows
        matches = []
        for j, in_row in enumerate(demo_pairs[0]['input']):
            if out_row == in_row:
                matches.append((j, j - i))  # (input_idx, shift)

        if matches:
            best = min(matches, key=lambda x: abs(x[1]))  # Minimize shift magnitude
